SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS ai_specialty_map;
DROP TABLE IF EXISTS ai_specialties;
DROP TABLE IF EXISTS doctor_concentrations;
DROP TABLE IF EXISTS concentrations;
DROP TABLE IF EXISTS doctor_chambers;
DROP TABLE IF EXISTS chambers;
DROP TABLE IF EXISTS doctor_specialties;
DROP TABLE IF EXISTS specialties;
DROP TABLE IF EXISTS doctors;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE IF NOT EXISTS doctors (
 id INT PRIMARY KEY, name VARCHAR(255) NOT NULL, education_text TEXT,
 experience_years INT NOT NULL DEFAULT 0, city VARCHAR(100) NOT NULL DEFAULT 'Dhaka',
 source_label VARCHAR(120) NOT NULL DEFAULT 'AmarCure imported doctor directory',
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX idx_doctors_name(name), INDEX idx_doctors_experience(experience_years)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS specialties (
 id INT PRIMARY KEY, name VARCHAR(180) NOT NULL UNIQUE, INDEX idx_specialty_name(name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS doctor_specialties (
 doctor_id INT NOT NULL, specialty_id INT NOT NULL, PRIMARY KEY(doctor_id,specialty_id),
 FOREIGN KEY(doctor_id) REFERENCES doctors(id) ON DELETE CASCADE,
 FOREIGN KEY(specialty_id) REFERENCES specialties(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chambers (
 id INT PRIMARY KEY, name VARCHAR(255) NOT NULL, area VARCHAR(160), city VARCHAR(100) NOT NULL DEFAULT 'Dhaka',
 address_text VARCHAR(500), latitude DECIMAL(10,7), longitude DECIMAL(10,7),
 geocode_status ENUM('pending','matched','manual','failed') NOT NULL DEFAULT 'pending',
 geocode_display_name VARCHAR(600), geocoded_at DATETIME,
 UNIQUE KEY uq_chamber_name_city(name,city), INDEX idx_chamber_geo(latitude,longitude), INDEX idx_chamber_city(city)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS doctor_chambers (
 doctor_id INT NOT NULL, chamber_id INT NOT NULL, appointment_numbers VARCHAR(255),
 PRIMARY KEY(doctor_id,chamber_id),
 FOREIGN KEY(doctor_id) REFERENCES doctors(id) ON DELETE CASCADE,
 FOREIGN KEY(chamber_id) REFERENCES chambers(id) ON DELETE CASCADE,
 INDEX idx_dc_chamber(chamber_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS concentrations (
 id INT PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS doctor_concentrations (
 doctor_id INT NOT NULL, concentration_id INT NOT NULL, PRIMARY KEY(doctor_id,concentration_id),
 FOREIGN KEY(doctor_id) REFERENCES doctors(id) ON DELETE CASCADE,
 FOREIGN KEY(concentration_id) REFERENCES concentrations(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ai_specialties (
 code VARCHAR(40) PRIMARY KEY, display_name VARCHAR(120) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ai_specialty_map (
 ai_code VARCHAR(40) NOT NULL, specialty_id INT NOT NULL, priority TINYINT NOT NULL DEFAULT 10,
 PRIMARY KEY(ai_code,specialty_id),
 FOREIGN KEY(ai_code) REFERENCES ai_specialties(code) ON DELETE CASCADE,
 FOREIGN KEY(specialty_id) REFERENCES specialties(id) ON DELETE CASCADE,
 INDEX idx_aism_specialty(specialty_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

START TRANSACTION;
COMMIT;